import pytest
from hypothesis import given, HealthCheck
from hypothesis import strategies as st

from solution import make_palindrome, is_palindrome


def _is_pal_ref(s: str) -> bool:
    return s == s[::-1]


def _reference_make_palindrome(s: str) -> str:
    # Obviously-correct implementation of the spec's algorithm idea:
    # longest postfix (suffix) that is a palindrome, then append
    # reverse of prefix before it.
    n = len(s)
    for i in range(n):
        suffix = s[i:]
        if suffix == suffix[::-1]:
            return s + s[:i][::-1]
    # empty suffix case: i == n -> append reverse of whole string minus?
    # For n == 0 loop doesn't run; handle below.
    # If no non-empty palindromic suffix (impossible since len-1 suffix
    # of length 1 is always palindrome for n>=1), fall back:
    return s + s[::-1] if n == 0 else s + s[:n][::-1]


# ---------- explicit spec examples ----------

def test_example_empty():
    assert make_palindrome('') == ''


def test_example_cat():
    assert make_palindrome('cat') == 'catac'


def test_example_cata():
    assert make_palindrome('cata') == 'catac'


# ---------- properties ----------

small_strings = st.text(alphabet=st.sampled_from("abac"), min_size=0, max_size=10)
small_strings2 = st.text(alphabet=st.sampled_from("abc"), min_size=0, max_size=12)


@given(small_strings)
def test_result_begins_with_input(s):
    r = make_palindrome(s)
    assert type(r) == str
    assert r.startswith(s)


@given(small_strings)
def test_result_is_palindrome(s):
    r = make_palindrome(s)
    # independent check, not trusting solution.is_palindrome
    assert r == r[::-1]


@given(small_strings)
def test_result_length_bounds(s):
    r = make_palindrome(s)
    assert len(r) >= len(s)
    if len(s) == 0:
        assert r == ''
    else:
        # s + reverse(s[:-1]) is always a palindrome beginning with s,
        # so shortest has length <= 2*len(s)-1
        assert len(r) <= 2 * len(s) - 1


@given(small_strings)
def test_result_is_shortest(s):
    r = make_palindrome(s)
    assert r.startswith(s)
    assert r == r[::-1]
    k = len(r) - len(s)
    # Any palindrome beginning with s with added length k' < k and k' < len(s)
    # must be of form s + reverse(s[:k']); verify none is palindrome.
    # (Proof: if p = s+t palindrome, |t|=k'<|s|, then t must equal reverse(s[:k'])).
    # Also need k < len(s) unless s empty; check that.
    if len(s) > 0:
        assert k < len(s) or r == s  # k==0 case
    for kp in range(k):
        if kp < len(s):
            cand = s + s[:kp][::-1]
            assert cand != cand[::-1] or len(cand) >= len(r), (
                f"shorter palindrome {cand!r} exists for {s!r}"
            )
    # Direct minimality: no palindrome starting with s shorter than r.
    # For lengths L in [len(s), len(r)), at most one candidate of the
    # append-form; but for full generality when len(s) < ceil(L/2) there
    # could be other palindromes starting with s not of append form.
    # Brute-force check via constraint solving for small sizes:
    # a palindrome of length L starting with s exists iff s is compatible
    # with its own reverse constraint.
    for L in range(len(s), len(r)):
        # Check existence: construct palindrome forced by s prefix where forced,
        # free variables elsewhere; check compatibility.
        # p[i] must equal p[L-1-i]. For i < len(s), p[i]=s[i].
        # So for every i < len(s), if L-1-i < len(s) then need s[i]==s[L-1-i],
        # else no constraint (free position can match s[i]).
        # Hence existence iff for all i<len(s) with L-1-i < len(s): s[i]==s[L-1-i].
        # i.e., the length-L prefix-constrained palindrome exists iff
        # the overlapping part is consistent.
        consistent = True
        for i in range(len(s)):
            j = L - 1 - i
            if 0 <= j < len(s):
                if s[i] != s[j]:
                    consistent = False
                    break
        assert not consistent, f"length {L} palindrome starting with {s!r} exists, got {r!r}"


@given(small_strings)
def test_palindromic_input_returns_itself(s):
    # Shortest palindrome beginning with a palindrome is itself.
    if s == s[::-1]:
        assert make_palindrome(s) == s


@given(small_strings2)
def test_equivalence_to_reference_model(s):
    assert make_palindrome(s) == _reference_make_palindrome(s)


@given(small_strings)
def test_idempotence(s):
    r = make_palindrome(s)
    assert make_palindrome(r) == r


@given(small_strings)
def test_append_form_structure(s):
    r = make_palindrome(s)
    k = len(r) - len(s)
    assert r == s + s[:k][::-1]
    # the suffix starting at k must be the longest palindromic suffix
    suffix = s[k:] if k <= len(s) else ''
    assert suffix == suffix[::-1]
    for i in range(k):
        assert s[i:] != s[i:][::-1], f"suffix s[{i}:]={s[i:]!r} is palindrome but longer than {suffix!r}"


def test_single_characters_unchanged():
    for c in ["a", "b", "z", "x"]:
        assert make_palindrome(c) == c


def test_already_palindrome_unchanged():
    for s in ["", "a", "aa", "aba", "abba", "abcba", "aaaa", "ababa"]:
        assert make_palindrome(s) == s


def test_longest_not_shortest_suffix():
    # Distinguishes longest-palindromic-suffix from shortest-palindromic-suffix.
    # 'cata' longest palindromic suffix is 'ata', giving 'catac'.
    assert make_palindrome("cata") == "catac"
    # 'ababa' is palindrome -> itself; 'aabaa' etc.
    assert make_palindrome("abac") == "abacaba"
    assert make_palindrome("aaaaab") == "aaaaabaaaaa"
    # suffix 'aa' vs 'a': longest is 'aa'
    assert make_palindrome("baa") == "baab"


@given(st.text(alphabet=st.sampled_from("ab"), min_size=1, max_size=8))
def test_prefix_extension_monotonic(s):
    # Appending one char to input cannot shrink the result below input length
    # and result must still start with the longer input.
    r1 = make_palindrome(s)
    r2 = make_palindrome(s + "a")
    assert r2.startswith(s + "a")
    assert r2 == r2[::-1]
